-- Lessons: text, Markdown, video and PDF, with prerequisites.
-- Tables: Lesson
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public."Lesson" (
    id text NOT NULL,
    "collegeId" text NOT NULL,
    title text NOT NULL,
    content text DEFAULT ''::text NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "moduleId" text NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    allow_download_in smallint DEFAULT 0 NOT NULL,
    duration_sec integer,
    file_id text,
    lesson_type public."LessonType" DEFAULT 'TEXT'::public."LessonType" NOT NULL,
    prerequisite_lesson_id text,
    published_in smallint DEFAULT 1 NOT NULL,
    content_fmt_cd public."ContentFormat" DEFAULT 'TEXT'::public."ContentFormat" NOT NULL,
    CONSTRAINT "Lesson_a_in_check" CHECK ((a_in = ANY (ARRAY[0, 1]))),
    CONSTRAINT "Lesson_duration_check" CHECK (((duration_sec IS NULL) OR (duration_sec >= 0))),
    CONSTRAINT "Lesson_flags_check" CHECK (((allow_download_in = ANY (ARRAY[0, 1])) AND (published_in = ANY (ARRAY[0, 1])))),
    CONSTRAINT "Lesson_prerequisite_self_check" CHECK (((prerequisite_lesson_id IS NULL) OR (prerequisite_lesson_id <> id)))
);

ALTER TABLE ONLY public."Lesson"
    ADD CONSTRAINT "Lesson_pkey" PRIMARY KEY (id);

CREATE INDEX "Lesson_collegeId_idx" ON public."Lesson" USING btree ("collegeId");

CREATE TRIGGER "Lesson_audit_timestamps" BEFORE UPDATE ON public."Lesson" FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

-- Foreign keys
ALTER TABLE ONLY public."Lesson"
    ADD CONSTRAINT "Lesson_moduleId_fkey" FOREIGN KEY ("moduleId") REFERENCES public."CourseModule"(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY public."Lesson"
    ADD CONSTRAINT "Lesson_prerequisite_lesson_id_fkey" FOREIGN KEY (prerequisite_lesson_id) REFERENCES public."Lesson"(id) ON UPDATE CASCADE ON DELETE SET NULL;

COMMIT;
